def stall_dict(s): return {k:getattr(s,k) for k in ['id','code','name','category','zone','owner_name','status','avg_ticket','occupancy_rate']}
def campaign_dict(c): return {k:(getattr(c,k).isoformat() if hasattr(getattr(c,k),'isoformat') else getattr(c,k)) for k in ['id','code','name','label','starts_at','ends_at','target_zone','status','owner','notes']}
def analysis_dict(a): return {'id':a.id,'name':a.name,'status':a.status,'review_status':a.review_status,'requested_by':a.requested_by,'sample_ids':a.sample_ids,'sample_count':a.sample_count,'result':a.result,'review_note':a.review_note,'created_at':a.created_at.isoformat() if a.created_at else None,'completed_at':a.completed_at.isoformat() if a.completed_at else None}
def brief_dict(b): return {'id':b.id,'analysis_id':b.analysis_id,'title':b.title,'status':b.status,'summary':b.summary,'recommended_stalls':b.recommended_stalls,'audience':b.audience,'created_at':b.created_at.isoformat() if b.created_at else None,'issued_at':b.issued_at.isoformat() if b.issued_at else None}
